def prep(q, cal=None):
    l = q['lab_id']
    s = q['stratum']
    f = q['coupon_features_raw']
    ref = q['ref_coupons']
    u = np.empty_like(f)
    if cal is None:
        cal = {}
        for a in np.unique(l):
            rr = ref[l == a]
            cal[a] = (np.nanmedian(np.nanmean(rr, axis=0)), np.nanmedian(np.nanstd(rr, axis=0)))
    for a in np.unique(l):
        ix = l == a
        (mu, sigma) = cal[a]
        u[ix] = (f[ix] - mu) / sigma
    return (u, cal)
